/*
 * A097294  Contains exactly once every triple i,j,k such that i>j>k>0.
 * https://oeis.org/A097294
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 104, u16 n <= 104, u32 n <= 104, u64 n <= 104,
 *            u128 n <= 104, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Generated by enumerating all ordered distinct triples (i,j,k)
   with i>j>k>0 in order of increasing sum s = i+j+k.
   For each fixed s the triples are listed by increasing k and,
   within each k, by increasing j (which automatically gives i>j). */
/* Pattern: a(1) = 3, a(2) = 2, a(3) = 1, ... as in OEIS A097294 */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;   /* safety for 0, not used in OEIS */

    /* count of terms already produced */
    idx_t produced = 0;

    /* sums start at 6 because smallest triple is (3,2,1) */
    for (idx_t sum = 6; ; ++sum) {
        /* k can range from 1 up to sum-3 (since j>k and i>j) */
        for (idx_t k = 1; k <= sum - 3; ++k) {
            /* j starts at k+1 and must satisfy i = sum - j - k > j */
            idx_t j_start = k + 1;
            idx_t j_end   = (sum - k - 1) / 2;     /* floor((sum-k-1)/2) */
            if (j_end < j_start) continue;        /* no valid j for this k */

            for (idx_t j = j_start; j <= j_end; ++j) {
                idx_t i_val = sum - j - k;        /* i > j guaranteed */

                /* output i */
                ++produced;
                if (produced == n) return (seq_t)i_val;

                /* output j */
                ++produced;
                if (produced == n) return (seq_t)j;

                /* output k */
                ++produced;
                if (produced == n) return (seq_t)k;
            }
        }
    }
}
